			if err != nil {
				return columnErrBuilder(errors.Wrap(err, "compute proposer"))
			}
		}

		if idx != dataColumn.ProposerIndex() {
			return columnErrBuilder(errSidecarUnexpectedProposer)
		}
	}

	return nil
}

